+var (
+	controlsHunkHeader  = regexp.MustCompile(`^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@`)
+	controlsPatchFailed = regexp.MustCompile(`patch failed: .*:(\d+)`)
+)
+
+const controlsExcerptLines = 8
+
+// controlsHunkDetail names the first hunk of a patch that did not apply (git's own report names its
+// old start line; without one, the first hunk) and shows up to controlsExcerptLines lines of the
+// file in the tree from that line, each prefixed with its line number. It is empty when the patch
+// has no hunk header.
+func controlsHunkDetail(tree, p, patch, gitOut string) string {
+	failed := -1
+	if m := controlsPatchFailed.FindStringSubmatch(gitOut); m != nil {
+		failed, _ = strconv.Atoi(m[1])
+	}
+	header, start := "", 0
+	for _, l := range strings.Split(patch, "\n") {
+		m := controlsHunkHeader.FindStringSubmatch(l)
+		if m == nil {
+			continue
+		}
+		n, _ := strconv.Atoi(m[1])
+		if header == "" || n == failed {
+			header, start = strings.TrimRight(l, "\r"), n
+		}
+		if n == failed {
+			break
+		}
+	}
+	if header == "" {
+		return ""
+	}
+	detail := "; first failed hunk: " + header
+	raw, err := os.ReadFile(filepath.Join(tree, filepath.FromSlash(p)))
+	if err != nil {
+		return detail + "; the file does not exist in the candidate tree"
+	}
+	lines := strings.Split(strings.TrimSuffix(string(raw), "\n"), "\n")
+	if start < 1 {
+		start = 1
+	}
+	var shown []string
+	for i := start; i <= len(lines) && i < start+controlsExcerptLines; i++ {
+		shown = append(shown, fmt.Sprintf("%d: %s", i, strings.TrimRight(lines[i-1], "\r")))
+	}
+	if len(shown) == 0 {
+		return detail + fmt.Sprintf("; the file has only %d lines", len(lines))
+	}
+	return detail + "; the file from line " + strconv.Itoa(start) + ": " + strings.Join(shown, " | ")
+}
